const NOCODB='https://appcadabra-nocodb.jmyxxj.easypanel.host';
const TID='mcp3sx8fm259gn6';
const NC_TOKEN='nc_pat_1wp_6l2kWvfLo2doqbPvr-vC_rCcLutaOnYox9KB';
const b = $input.first().json.body || {};
const req = async (method, url, headers, body) => {
  try { const opt={ method, url, headers, json:true }; if(body) opt.body=body; return await this.helpers.httpRequest(opt); }
  catch(e){ return (e.response&&e.response.body)?e.response.body:{ __err:String(e.message||e) }; }
};
const event = b.event;
const wa = (((b.conversation||{}).meta||{}).sender||{}).identifier         || ((b.meta||{}).sender||{}).identifier         || (b.sender||{}).identifier         || (b.contact||{}).identifier || '';
const NCH={ 'xc-token':NC_TOKEN, 'Content-Type':'application/json' };
const setBot = async (activo) => {
  if(!wa) return;
  const q = await req('GET', `${NOCODB}/api/v2/tables/${TID}/records?where=(contact_id,eq,${wa})&limit=1`, NCH);
  const row = q && q.list && q.list[0];
  if(row) await req('PATCH', `${NOCODB}/api/v2/tables/${TID}/records`, NCH, { Id: row.Id, bot_activo: activo });
};
// PRIORIDAD 1: mensaje de un vendedor (message_created outgoing, sin marca espejo).
// Va PRIMERO: un mensaje del vendedor SIEMPRE toma el control, aunque el evento
// traiga status=resolved heredado de la conversación.
if (event==='message_created') {
  const esOutgoing = (b.message_type==='outgoing' || b.message_type===1);
  const esEspejo = !!(b.content_attributes && b.content_attributes.espejo);
  const contenido = (b.content||'').trim();
  if (esOutgoing && !esEspejo && contenido && wa) {
    await setBot(false);
    return [{ json:{ reenviar:true, wa, contenido } }];
  }
  return [{ json:{ reenviar:false, accion:'ignorado', motivo: esEspejo?'espejo':(!esOutgoing?'incoming':'sin_contenido') } }];
}
// PRIORIDAD 2: conversación RESUELTA (solo en conversation_updated) -> reactivar bot.
if (event==='conversation_updated' || event==='conversation_resolved') {
  const resuelto = (event==='conversation_resolved') || (b.status==='resolved') || (((b.conversation||{}).status)==='resolved');
  if (resuelto) { await setBot(true); return [{ json:{ reenviar:false, accion:'bot_reactivado', wa } }]; }
}
return [{ json:{ reenviar:false, accion:'evento_ignorado', event } }];
